<section class="billingSummaryGrid"><article class="card"><span class="meta">Billing account</span><strong><?=h((string)$account['name'])?></strong><small><?=h((string)$account['account_type'])?> account</small></article><article class="card"><span class="meta">Current package</span><strong><?=h((string)$account['package_name'])?></strong><small><?=h((string)$account['subscription_status'])?> · <?=h((string)($account['billing_source']??'manual'))?></small></article><article class="card"><span class="meta">Monthly price</span><strong><?=h($displayCurrency)?> <?=h(number_format($displayAmount/100,2))?></strong><small><?=$displayPrice?'Current Stripe Price':'Annotated package price'?></small></article><article class="card"><span class="meta">AI tokens</span><strong><?=$usage?($usage['remaining_tokens']===null?'Uncapped':h(number_format((int)$usage['remaining_tokens'])).' remaining'):'—'?></strong><small><?=$usage?h(number_format((int)$usage['used_tokens'])).' used this period':'Usage unavailable'?></small></article><article class="card"><span class="meta">Billing period</span><strong><?=h((string)$account['period_start'])?></strong><small>through <?=h((string)$account['period_end'])?></small></article></section>
