<?php if(!$subscription):?><section class="card"><div class="sectionHeadWeb"><div><span class="eyebrow">PLANS</span><h2>Choose a paid package</h2></div></div><?php if(!$configured):?><p class="empty">Online billing is not available yet. This account remains under its existing package state.</p><?php else:?><div class="billingPlanGrid"><?php foreach($packages as $p):if((int)$p['monthly_price_cents']<=0)continue;$map=$p['stripe_price']??null;?><article class="billingPlanCard"><h3><?=h((string)$p['name'])?></h3><div class="billingPlanPrice">$<?=h(number_format(((int)$p['monthly_price_cents'])/100,2))?><small>/ month</small></div><p><?=h((string)($p['description']??''))?></p><div class="meta"><?=h(number_format((int)($p['monthly_ai_token_allowance']??0)))?> AI tokens · <?=h((string)$p['member_limit'])?> member<?=((int)$p['member_limit']===1?'':'s')?></div><?php if($map):?><form method="post"><?=csrf_field()?><input type="hidden" name="account" value="<?=h((string)$account['public_id'])?>"><input type="hidden" name="op" value="checkout"><input type="hidden" name="package_id" value="<?=h((string)$p['public_id'])?>"><button><?=((int)$account['package_id']===(int)$p['id'])?'Start paid billing':'Choose '.h((string)$p['name'])?></button></form><?php else:?><span class="meta">Online purchase not configured for this package.</span><?php endif?></article><?php endforeach?></div><?php endif?></section><?php endif?>
